preConditionHook:
// MultiWalk's WFSafe_ADX == WFSafe_DirMovement (el_source_wfsafe_dirmovement.txt
// in the engine repo), ported statement for statement and verified BIT FOR BIT
// against TradeStation on 18,081 bars of @OJ 240min across two chart starts
// (EL_ADX_Probe.txt; scripts/adx_replica.py). Three findings the code below is
// carrying, all measured:
//
//  * The chain seeds at the study's FIRST CALCULATED BAR -- the function's
//    CurrentBar is the study's -- with fresh Length-term DM/TR sums, followed by
//    EMA-form updates Avg = Avg[1] + SF*(X - Avg[1]), SF = 1/Length. oADX
//    warms up as Cum(oDMI)/CurrentBar through bar Length, and beyond it as
//    oADX = oADX[1] + SF*(oDMI - oADX[1]). Warm-up values are live and gate
//    real entries, exactly as in EL.
//  * el_gt in the DM classification is DECISIVE, not defensive: UpperMove and
//    LowerMove are differences of grid prices, so float noise manufactures
//    near-ties that EL's 2.22e-12 tolerance collapses. Measured at @OJ
//    2010-02-01 12:00 (up = 1.0499999999999998 vs dn = 1.0500000000000007):
//    raw > assigns MinusDM = 1.05, EL assigns nothing, and that one bar was
//    the whole 2010-run seed mismatch. The TrueRange ternaries below compare
//    raw grid prices, where the tolerance cannot bind.
//  * Unlike WFSafe_AvgTrueRange there is NO re-seed on a length change -- the
//    WFSafe_ modification is only that SF tracks Length per bar -- so no
//    length-change guard here.
//
// sfAdx/dmiPlus/dmiMinus/divisor/dmi are declared as rule locals (class
// members), not inline: an inline declaration is not renamed by the
// generator and collides when two occurrences of this rule share one
// strategy version. Each is fully assigned every bar before use.
sfAdx = 1 / lookback;
if (ctx.CurrentBar() == 1) {
    double sumPlusDM = 0.0;
    double sumMinusDM = 0.0;
    double sumTR = 0.0;
    for (int i = 0; i < (int)lookback; ++i) {
        double upMove = high[i] - high[i + 1];
        double dnMove = low[i + 1] - low[i];
        double plusDM = 0.0;
        double minusDM = 0.0;
        if (el_gt(upMove, dnMove) && el_gt(upMove, 0.0)) plusDM = upMove;
        else if (el_gt(dnMove, upMove) && el_gt(dnMove, 0.0)) minusDM = dnMove;
        sumPlusDM += plusDM;
        sumMinusDM += minusDM;
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        sumTR += hi - lo;
    }
    avgPlusDM = sumPlusDM / lookback;
    avgMinusDM = sumMinusDM / lookback;
    volty = sumTR / lookback;
} else {
    double upMove = high[0] - high[1];
    double dnMove = low[1] - low[0];
    double plusDM = 0.0;
    double minusDM = 0.0;
    if (el_gt(upMove, dnMove) && el_gt(upMove, 0.0)) plusDM = upMove;
    else if (el_gt(dnMove, upMove) && el_gt(dnMove, 0.0)) minusDM = dnMove;
    avgPlusDM = avgPlusDM + sfAdx * (plusDM - avgPlusDM);
    avgMinusDM = avgMinusDM + sfAdx * (minusDM - avgMinusDM);
    double hi = high[0] > close[1] ? high[0] : close[1];
    double lo = low[0] < close[1] ? low[0] : close[1];
    volty = volty + sfAdx * ((hi - lo) - volty);
}
dmiPlus = 0.0;
dmiMinus = 0.0;
if (el_gt(volty, 0.0)) {
    dmiPlus = 100 * avgPlusDM / volty;
    dmiMinus = 100 * avgMinusDM / volty;
}
divisor = dmiPlus + dmiMinus;
dmi = 0.0;
if (el_gt(divisor, 0.0)) dmi = 100 * std::fabs(dmiPlus - dmiMinus) / divisor;
// Cum() is a series function: it accumulates every bar regardless of which
// oADX branch runs.
cumDmi = cumDmi + dmi;
if (ctx.CurrentBar() <= lookback) {
    adxVal = cumDmi / ctx.CurrentBar();
} else {
    adxVal = adxVal + sfAdx * (dmi - adxVal);
}
